const items = $input.all();
const meta = $("Extract Email Metadata").first();
const expectedYear = meta.json.year;
const match = items.find(i => (i.json.name || "") === expectedYear);
return [{ json: { ...meta.json, year: meta.json.year, yearFolderId: match ? match.json.id : "", yearExists: !!match }, binary: meta.binary || {} }];

const items = $input.all();
const meta = $("Set Year Folder ID").first();
const expectedVendor = meta.json.senderFolder;
const match = items.find(i => (i.json.name || "") === expectedVendor);
return [{ json: { ...meta.json, vendorFolderId: match ? match.json.id : "", vendorFolderExists: !!match }, binary: meta.binary || {} }];

const checkResult = $input.all();
const meta = $("Set Vendor Folder ID").first();
const isDuplicate = checkResult.length > 0 && checkResult[0].json["File Name"];
if (isDuplicate) {
  return [];
} else {
  return [{ json: { ...meta.json }, binary: meta.binary || {} }];
}

const meta = $input.item.json;
if (meta.vendorFolderExists) {
  return { json: { ...meta }, binary: $input.item.binary || {} };
} else {
  const createdFolder = $("Create Vendor Folder").item.json;
  return { json: { ...meta, vendorFolderId: createdFolder.id }, binary: $input.item.binary || {} };
}

const meta = $input.item.json;
if (meta.yearExists) {
  return { json: { ...meta }, binary: $input.item.binary || {} };
} else {
  const createdFolder = $("Create Year Folder").item.json;
  return { json: { ...meta, yearFolderId: createdFolder.id }, binary: $input.item.binary || {} };
}
